Create `src/components/shared/PaletteProvider.tsx` — a client component that wraps the site and applies palette CSS vars:
```tsx
'use client';
export function PaletteProvider({ palette, children }: { palette: Palette, children: React.ReactNode }) {
  return (
    <div style={palette.tokens as React.CSSProperties}>
      {children}
    </div>
  );
}
```
